<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api,connect,disconnect,state,stamp} from '../api'
import {APP_NAME} from '../branding'
const emit=defineEmits<{settings:[]}>()
const data=ref<any>(),line=ref(''),workshop=ref(''),clock=ref(new Date().toLocaleTimeString('zh-CN',{hour12:false})),error=ref('');let poll:ReturnType<typeof setInterval>,tick:ReturnType<typeof setInterval>
const workshops=computed<string[]>(()=>Array.from(new Set<string>((data.value?.lines||[]).map((x:any)=>x.workshop))))
async function refresh(){try{const q=new URLSearchParams();if(line.value)q.set('lineId',line.value);if(workshop.value)q.set('workshop',workshop.value);data.value=await api('/api/tv?'+q);state.lastUpdate=data.value.at;error.value=''}catch(e:any){error.value=e.message}}
onMounted(async()=>{await refresh();await connect(refresh,true);poll=setInterval(async()=>{await refresh();if(!state.connected)await connect(refresh,true)},15000);tick=setInterval(()=>clock.value=new Date().toLocaleTimeString('zh-CN',{hour12:false}),1000)});onUnmounted(()=>{clearInterval(poll);clearInterval(tick);disconnect()})
function fullscreen(){document.documentElement.requestFullscreen?.()}
</script>
<template><main class="mes-tv"><header><div class="board-brand">{{APP_NAME}}</div><h1>生产运行实时看板</h1><div class="actions"><select v-model="workshop" @change="line='';refresh()"><option value="">全部车间</option><option v-for="w in workshops" :key="w">{{w}}</option></select><select v-model="line" @change="refresh"><option value="">全部产线</option><option v-for="l in data?.lines.filter((l:any)=>!workshop||l.workshop===workshop)" :key="l.id" :value="l.id">{{l.name}}</option></select><button @click="emit('settings')">服务器设置</button><button @click="fullscreen">全屏</button><b>{{clock}}</b></div></header><div class="tv-metrics"><div v-for="(label,k) in {started:'主码投入',completed:'包装完成',yield:'最新测试合格率',online:'在线工位'}" :key="k"><span>{{label}}</span><strong>{{k==='online'?data?.stations.filter((s:any)=>s.online).length||0:data?.[k]||0}}{{k==='yield'?'%':''}}</strong></div></div><div class="tv-columns"><section><h2>工单进度</h2><div v-for="o in data?.orders.slice(0,7)" :key="o.id" class="tv-order"><b>{{o.code}}</b><div><div class="progress"><i :style="{width:Math.min(100,o.completed/o.plan*100)+'%'}"/></div><small>{{o.completed}} / {{o.plan}}</small></div><strong>{{(o.completed/o.plan*100).toFixed(1)}}%</strong></div></section><section><h2>最新仪器结果</h2><table><thead><tr><th>主码</th><th>结果</th><th>时间</th></tr></thead><tbody><tr v-for="t in data?.tests.slice(0,8)" :key="t.receivedAt+t.mainCode"><td>{{t.mainCode}}</td><td :class="t.verdict==='PASS'?'pass':'fail'">{{t.verdict}}</td><td>{{new Date(t.receivedAt).toLocaleTimeString('zh-CN',{hour12:false})}}</td></tr></tbody></table></section><section><h2>异常接收</h2><div v-for="(e,i) in data?.exceptions" :key="i" class="tv-exception"><b>{{e.device}}</b><p>{{e.reason}}</p></div><p v-if="!data?.exceptions.length">暂无异常接收记录</p></section></div><div class="tv-flow"><div v-for="p in data?.processes" :key="p.id"><small>0{{p.sequence}}</small><b>{{p.name}}</b><strong>{{p.completed}}</strong></div></div><footer><span :class="{'fail':!state.connected||!state.online}">{{state.connected&&state.online?'● 实时连接正常':'● 连接中断 / 重连中'}} {{error}}</span><span>最后更新 {{stamp(state.lastUpdate)}} · 每 15 秒自动校验快照</span></footer></main></template>
